// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 g) public {
        vm.assume(actor != address(0) && actor != address(c));

        // actor locks in an arbitrary guess with exactly 1 ether
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);

        // jump one block past the target block so settle() is admissible
        vm.roll(block.number + 2);

        // first settle: admissible in both versions, always succeeds
        vm.prank(actor);
        c.settle();

        // general rule: settle() consumed the guess, so a second settle()
        // by the same actor must revert (target block is 0 in the reference)
        bool ok;
        vm.prank(actor);
        try c.settle() { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
